using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ResinChecks {
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 [MenuItem("BWVR/Verify renewable resin accounting")]
 public static void VerifyModel(){var s=new ResourceState();var wood=s.Ensure("tree",VillageResource.Wood);var resin=s.EnsureResin(wood.id);Require(resin!=null&&resin.remaining==4&&s.Valid(),"Linked resin source invalid");Require(s.Harvest(0,resin.id,99)==2&&wood.remaining==12&&!wood.felled,"Tapping damaged tree or overfilled jar");s.RenewResin(resin.id,1000,true);Require(resin.remaining==2&&s.Valid(),"Regeneration stole pending cargo capacity");Require(s.Harvest(1,wood.id,3)==0,"Logging erased resin in transit");var pending=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(s));Require(pending.Valid(),"Resin cargo save invalid");pending.Recover(0);Require(pending.Find(resin.id).remaining==4&&pending.resin==0,"Reload recovery created/lost resin");Require(s.Deposit(0)==2&&s.resin==2&&s.wheat==6&&s.wood==0&&s.Deposit(0)==0,"Resin deposited into wrong stock or duplicated");s.RenewResin(resin.id,90,false);Require(resin.remaining==2,"Unsafe tree regenerated");s.RenewResin(resin.id,90,true);Require(Mathf.Abs(resin.remaining-3)<.001f,"Living-tree regeneration rate wrong");Require(s.Harvest(1,resin.id,2)==2,"Second resin harvest failed");s.resin=s.Limit(VillageResource.Resin);Require(s.Deposit(1)==0&&resin.remaining==3,"Full store lost resin");Require(s.Harvest(0,wood.id,3)==3&&wood.felled&&resin.remaining==0,"Logging did not end tapping");s.Deposit(0);s.RenewResin(resin.id,1000,true);Require(resin.remaining==0&&s.Harvest(0,resin.id,2)==0,"Stump yielded resin");for(int i=0;i<3;i++){s.Harvest(0,wood.id,3);s.Deposit(0);}Require(s.Plant(wood.id),"Cannot replant tapped tree");s.RenewResin(resin.id,90,true);Require(resin.remaining==0,"Sapling yielded resin");s.Grow(wood.id,300);s.RenewResin(resin.id,90,true);Require(Mathf.Abs(resin.remaining-1)<.001f&&s.Valid(),"Mature replanted tree did not resume resin");var corrupt=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(s));corrupt.Find(resin.id).treeId="missing";Require(!corrupt.Valid(),"Orphan resin source accepted");Require(new SliceState().Valid(),"Legacy season invalid");Debug.Log("BWVR_RESIN_MODEL_PASS: living-tree tap, bounded replenishment, pending cargo, logging exclusion, stocks, overflow recovery, cut/growing trees, replant renewal and save validation");}
 [MenuItem("BWVR/Verify native resin gathering (Play mode)")]
 public static void VerifyRuntime(){Require(EditorApplication.isPlaying,"Enter Play mode");var world=UnityEngine.Object.FindAnyObjectByType<VillageResources>();var slice=world.GetComponentInParent<QuestSlice>();var field=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)field.GetValue(slice);var positions=world.Gatherers.Select(a=>a.transform.position).ToArray();slice.GetComponentInChildren<CreatureHybrid>().Interrupt("Resin QA");foreach(var a in world.Gatherers){a.Cancel();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();}var test=new SliceState{developmentFocus=true};field.SetValue(slice,test);world.ResetWorld();try{var node=world.sources.First(s=>s.kind==VillageResource.Resin&&world.Available(s));var wood=world.sources.First(s=>s.kind==VillageResource.Wood&&s.tree==node.tree);var record=test.Resources.Find(node.id);var actor=world.Gatherers[1];actor.transform.position=node.approach;actor.GetComponent<IslandNavigator>().ResetRoute();Require(actor.TryBegin(node)&&!world.Gatherers[2].TryBegin(wood)&&!world.Gatherers[2].TryBegin(node),"Tappers/loggers share a tree simultaneously");actor.Tick(30,true);world.Advance(30,true);Require(record.remaining==4&&test.Resources.resin==0,"Paused resin progressed");for(int n=0;n<2000&&actor.Current!=VillagerResourceGathering.Phase.Carry;n++)actor.Tick(.05f,false);Require(actor.Current==VillagerResourceGathering.Phase.Carry&&test.Resources.cargo[1].kind==VillageResource.Resin&&test.Resources.cargo[1].amount==2&&!node.tree.Harvested&&!test.Resources.Find(wood.id).felled,"Tapping did not carry resin/preserve tree");world.Advance(90,false);Require(record.remaining==2,"Cargo regenerated underneath carrier");actor.GetComponent<CarryItem>().held=true;actor.Tick(.1f,false);actor.GetComponent<CarryItem>().held=false;Require(!actor.Active&&record.remaining==4&&test.Resources.resin==0&&node.owner==null&&!node.tree.ResourceReserved,"Interrupted resin job lost cargo/ownership");Require(actor.TryBegin(node),"Cannot retry tapping");for(int n=0;n<4000&&actor.Active;n++)actor.Tick(.05f,false);Require(!actor.Active&&test.Resources.resin==2&&test.Resources.wood==0,"Native resin delivery failed");world.Refresh();Require(world.transform.Find("Stored resin jar 0").gameObject.activeSelf,"Stored resin not visible");var restored=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(restored.Valid(),"Resin season save invalid");field.SetValue(slice,restored);world.ResetWorld();float amount=restored.Resources.Find(node.id).remaining;world.Advance(90,false);Require(Mathf.Abs(restored.Resources.Find(node.id).remaining-Mathf.Min(4,amount+1))<.001f,"Saved resin did not replenish");Require(actor.TryBegin(wood),"Cannot choose logging after tapping");actor.Cancel();Require(restored.Valid(),"Final resin state invalid");Debug.Log("BWVR_RESIN_RUNTIME_PASS: native tapping/carry/deposit, shared-tree exclusion, protected living tree, pause, carried-worker recovery, amber jars and saved replenishment");}finally{foreach(var a in world.Gatherers)a.Cancel();field.SetValue(slice,original);world.ResetWorld();for(int i=0;i<positions.Length;i++){world.Gatherers[i].transform.position=positions[i];world.Gatherers[i].GetComponent<IslandNavigator>().ResetRoute();}}}
}
}
